async Awaitable PatrolAsync()
{
    var ct = destroyCancellationToken;            // взять, пока объект жив
    Patrols.Add(this);
    try
    {
        while (true)
        {
            await Awaitable.WaitForSecondsAsync(2f, ct); // уничтожили — бросит здесь
            MoveToNextPoint();
        }
    }
    catch (OperationCanceledException) { }        // отмена — не ошибка
    finally { Patrols.Remove(this); }             // уборка выполнится и при отмене
}

