// 1. Корутина: MoveNext зовёт Unity
IEnumerator Patrol()
{ while (true) { Step(); yield return new WaitForSeconds(2f); } }

// 2. Awaitable (Unity 2023.1+): останавливает только токен
async Awaitable PatrolAsync(CancellationToken ct)
{ while (true) { Step(); await Awaitable.WaitForSecondsAsync(2f, ct); } }

// 3. UniTask (Cysharp): так же — токеном
async UniTask PatrolUniAsync(CancellationToken ct)
{ while (true) { Step(); await UniTask.Delay(2000, cancellationToken: ct); } }
